export const SETTINGS_MODULES = ["cpu","gpu","memory","power","network","disk","battery"] as const;

export const SIZE_LIMITS_MB = [150,300,500,1000] as const;

/* Types */
/**  Why an alert fired. */
export type AlertCause = { type: "process_cpu"; process: string; cpu_pct: number | null } | { type: "thermal_state"; state: ThermalState };

/**
 *  The built-in alert rules (v1.2), each off until the user turns it on. Turning one on
 *  posts a one-off "Alerts are on" notification: macOS asks for notification permission
 *  on a first delivery, not when the app asks (D-084), so this brings the prompt up
 *  while the user is in Settings rather than with the first real alert.
 */
export type AlertSettings = {
	/**  [`AlertRule::hot_process`]: a process above 200% CPU for 5 minutes. */
	hot_process: boolean,
	/**  [`AlertRule::thermal_serious`]: thermal state Serious or worse. */
	thermal_serious: boolean,
};

export type AlertsPatch = {
	hot_process?: boolean | null,
	thermal_serious?: boolean | null,
};

/**  One app's bytes over a range. Bytes are exact below 2^53. */
export type AppBytes = {
	/**  The app as a user names it ("Google Chrome", "Safari", `curl`), D-089. */
	name: string,
	rx_bytes: number,
	tx_bytes: number,
};

/**
 *  One app's energy: its processes', summed (D-093). Helpers count toward their app
 *  by the identity rule per-app network uses (D-089).
 */
export type AppEnergy = {
	/**  "Google Chrome", "Safari", `node`; the process name when no app was resolved. */
	name: string,
	energy_j: number | null,
	avg_w: number | null,
	/**
	 *  The process that Quit on the app's row acts on: its running main executable,
	 *  or, for an app without one (a CLI), its only running process. `null` when
	 *  neither exists; each running process can still be quit on its own.
	 */
	quit_pid: number | null,
	/**  Largest first. */
	processes: ProcessEnergy[],
};

export type Appearance = "system" | "light" | "dark";

/**  One local hour of `battery_hours`. */
export type BatteryHour = {
	/**  The hour's start, as the request gave it. */
	start_ms: number,
	/**
	 *  `battery.charge` in the hour's last minute that sampled it; `null` when none did,
	 *  never 0.
	 */
	charge: number | null,
	/**  Whether `battery.charging` was on in any minute of the hour. */
	charging: boolean,
};

/**  A byte count as a plain JS `number`; exact below 2^53 (8 PiB). */
export type ByteCount = number;

/**  What a host can measure right now, per module. */
export type Capabilities = {
	/**  Entries for modules this build does not know are dropped on decode (D-040). */
	modules: Partial<{ [key in Module]: ModuleCap }>,
	/**
	 *  Increases on every change, so a receiver can drop a stale update. Exported to TS
	 *  as `number`; see [`crate::JS_SAFE_INT_MAX`].
	 */
	revision: number,
	/**
	 *  Process rows can carry network rates (`net_rx_bps`, `net_tx_bps`) while a view asks
	 *  for them: the in-process NetworkStatistics API loaded and the build may use it
	 *  (D-081). When false the UI hides the network columns. Defaults to false when a
	 *  sender does not know it.
	 */
	process_network?: boolean,
	/**
	 *  Process rows can carry GPU time (`gpu_pct`) while a view asks for it: the GPU's
	 *  IORegistry user clients report per-process `accumulatedGPUTime` and the build may
	 *  read them (D-085). When false the UI hides the GPU columns. Defaults to false.
	 */
	process_gpu?: boolean,
};

/**  Emitted when a host's capabilities change (a module appears or goes away). */
export type CapabilitiesChanged = {
	host: HostId,
	capabilities: Capabilities,
};

/**  The dashboard chart window (D-091). Every option fits the engine's 1-hour ring. */
export type ChartWindow = "5m" | "15m" | "30m" | "1h";

/**  One CPU cluster and its DVFS state table. */
export type ClusterInfo = {
	/**  The `cluster` label value used by `cpu.cluster.*` series, for example "P0" or "E0". */
	name: string,
	kind: CoreKind,
	/**  The `core` label values of the cores in this cluster, for example `["P0", "P1"]`. */
	cores: string[],
	/**
	 *  DVFS operating points in MHz, ascending. The last entry is the cluster's maximum
	 *  frequency (the CPU page's "max 4.51" ring label). These are also the `state` label
	 *  values of `cpu.cluster.residency` besides `idle`.
	 */
	dvfs_mhz: number[],
};

export type CommandError = 
/**  No host with this id is registered. */
{ kind: "unknown_host"; host: HostId } | 
/**
 *  The host is not this Mac, and the data asked for is kept only on the host it
 *  describes: per-app network bytes are not synced (D-089).
 */
{ kind: "remote_host"; host: HostId } | 
/**
 *  There is no history store: it could not be opened at launch, the local host could
 *  not be registered in it, or a reset failed. Kelvo runs live-only. `reason` says
 *  why when it is known; `reset_history` can recover from everything but `locked`.
 */
{ kind: "history_unavailable"; reason?: HistoryUnavailableReason | null } | 
/**
 *  The database is busy (another writer holds it, or a lock wait timed out). Worth one
 *  retry.
 */
{ kind: "store_busy"; message: string } | 
/**  The database file is damaged. `reset_history` moves it aside and starts a new one. */
{ kind: "store_corrupt"; message: string } | 
/**  A newer Kelvo wrote the database; this build cannot read it. */
{ kind: "store_too_new"; found: number; supported: number } | 
/**  Any other history query or write failure. */
{ kind: "store"; message: string } | 
/**  A bug or a crashed worker inside Kelvo (a command's task panicked). Not retryable. */
{ kind: "internal"; message: string } | 
/**  The settings patch produced settings that fail validation. Nothing changed. */
{ kind: "invalid_settings"; message: string } | 
/**  The settings file could not be written. Nothing changed. */
{ kind: "settings_not_saved"; message: string } | 
/**  Registering or unregistering the login item failed. Nothing changed. */
{ kind: "launch_at_login"; message: string } | 
/**  An argument is out of range (a negative span, an empty selector list). */
{ kind: "invalid_argument"; message: string } | 
/**  A window could not be created or shown. */
{ kind: "window"; message: string } | 
/**
 *  The export file could not be created or written (no permission, disk full). No
 *  partial file is left behind.
 */
{ kind: "export"; message: string } | 
/**
 *  The public address lookup failed: offline, the service unreachable or timing
 *  out, or an answer that is not an address (a captive portal).
 */
{ kind: "public_ip"; message: string };

export type CoreKind = "performance" | "efficiency" | 
/**  A core type this build does not know, from a newer peer (D-040). */
"unknown";

/**  Returned by `get_edition`. Fixed for the life of the process. */
export type Edition = {
	/**
	 *  Quit and Force Quit on the Processes page. False in the App Store edition, where
	 *  `process_signal` answers `unavailable`; the UI should hide the actions.
	 */
	process_signal: boolean,
};

/**
 *  `query_energy_by_app`: which apps used energy over a range, from the last hour of
 *  process samples Kelvo keeps in memory (D-093). CPU energy as the kernel estimates
 *  it per process; GPU, display and other users' processes are not attributed.
 */
export type EnergyByApp = {
	/**  The range the sums cover: the request widened to whole 10 s buckets. */
	from_ms: number,
	to_ms: number,
	/**
	 *  When Kelvo started counting (this launch, or the last history clear); `null`
	 *  before the first process sample. After `from_ms`, the range is covered only from
	 *  here.
	 */
	since_ms: number | null,
	/**  How much of the range was measured, ms; the averages divide by it. */
	measured_ms: number,
	/**  Every app's joules, summed: what shares are of. */
	total_j: number | null,
	/**  Largest first. */
	apps: AppEnergy[],
};

export type Event = {
	/**
	 *  When the event was detected: the row's `ts`. Two events of one kind never share
	 *  it (the store upserts on host, ts and kind).
	 */
	ts_ms: number,
	/**
	 *  Where the episode began (the start of a ramp, a spike or a sustained run); equal
	 *  to `ts_ms` for an instant change. The Timeline shades `start_ms..ts_ms`.
	 */
	start_ms: number,
	/**
	 *  Process names held responsible, most responsible first. Names, not pids: a pid
	 *  means nothing once the process is gone. Empty when nothing stood out.
	 */
	processes: string[],
	detail: EventDetail,
};

/**
 *  What happened. Internally tagged with the `events.kind` text, so a payload reads
 *  alone. There is no `Unknown` variant (D-040's fallback): `#[serde(other)]` cannot be
 *  exported to TypeScript with serde phases off, and an event is a whole row, so a kind
 *  from a newer build fails to decode and the reader skips that row (D-083).
 */
export type EventDetail = 
/**  The fastest fan rose by at least the threshold within the window. */
{ kind: "fans_ramped"; from_rpm: number | null; to_rpm: number | null } | 
/**
 *  `thermal.state` changed level and held it. `from` is `None` only when the
 *  previous level was never seen.
 */
{ kind: "thermal_state"; from: ThermalState | null; to: ThermalState } | 
/**  One process stayed above the CPU threshold for the whole duration. */
{ kind: "sustained_process"; process: string; 
/**  Mean CPU (percent of one core) over the run. */
cpu_pct: number | null; secs: number } | 
/**  A power component rose well above its rolling baseline and stayed there. */
{ kind: "power_spike"; component: PowerComponent; 
/**  Peak watts during the spike so far. */
watts: number | null; baseline_watts: number | null } | 
/**  An alert rule fired. */
{ kind: "alert"; rule_id: string; rule_name: string; cause: AlertCause };

/**
 *  Emitted when a detector or alert rule records an event (v1.2). The event is queued
 *  to the store with a commit request behind it, not yet committed: `query_events` returns
 *  it within one writer round trip, so a query racing this event can miss it. Windows
 *  merge it into what they hold instead of fetching again.
 */
export type EventRecorded = {
	host: HostId,
	event: Event,
};

/**  What `export_csv` did. Cancelling the dialog is not an error. */
export type ExportOutcome = { kind: "saved"; 
/**  Where the file went. */
path: string; 
/**  Bucket rows written, not counting the header or gap rows. */
rows: number; 
/**  Gap rows written. */
gap_rows: number; 
/**  File size. */
bytes: number } | 
/**  The user closed the dialog. Nothing was written. */
{ kind: "cancelled" };

/**  `export_csv`: what to write. Rust asks where with a save dialog. */
export type ExportRequest = {
	host: HostId,
	selectors: SeriesSelector[],
	/**  Inclusive start, ms epoch. */
	from_ms: number,
	/**  Exclusive end, ms epoch. */
	to_ms: number,
	/**
	 *  `auto` writes the tier a history read of the range would use, one row per bucket
	 *  (no merging).
	 */
	tier: TierRequest,
	/**
	 *  The file name the dialog proposes (`kelvo-2026-10-04.csv`); local dates are the
	 *  frontend's to format. Path separators are dropped. Default `kelvo-history.csv`.
	 */
	file_name?: string | null,
};

/**
 *  An explicit span with no data. Charts split series at gaps; nothing interpolates
 *  across one.
 * 
 *  `module` is `None` for a whole-host gap and `Some` only for
 *  [`GapReason::ModuleDisabled`] (or a [`GapReason::Unknown`] reason from a newer peer,
 *  which may scope a gap to a module), so charts for other modules ignore it. [`Gap::new`]
 *  enforces that pairing; the fields are public for decoding and the store, so callers
 *  that build one by hand should call [`Gap::validate`].
 */
export type Gap = {
	/**  Millisecond epoch, host clock. Exported to TS as `number`. */
	start_ms: number,
	/**  `None` while the gap is still open (asleep now, paused now). */
	end_ms: number | null,
	module: Module | null,
	reason: GapReason,
};

/**
 *  Why nothing was measured for a span. Stored as snake_case text in `gaps.reason`
 *  ([`GapReason::as_str`]).
 */
export type GapReason = 
/**  The machine slept. Written by the engine on `WillSleep`, closed on `DidWake`. */
"sleep" | 
/**
 *  Kelvo was not running. Written by the store on startup, from the last persisted
 *  bucket to now.
 */
"app_not_running" | 
/**  The user paused sampling. */
"paused" | 
/**  A module was switched off in Settings. The only reason that sets [`Gap::module`]. */
"module_disabled" | 
/**  (v4) The agent pruned past the controller's cursor. */
"truncated" | 
/**  (v4) A remote connection dropped. Provisional until sync catches up. */
"source_offline" | 
/**
 *  The wall clock stepped (a manual change or an NTP step) while sampling. Covers the
 *  wall-clock span the engine could not persist: a forward step's skipped span, or,
 *  after a backward step, the time until the clock is past what was already written
 *  (D-064).
 */
"clock_changed" | 
/**
 *  A batch of history failed to commit and its rows were lost. Written over the lost
 *  span by the next successful commit (D-064).
 */
"write_failed" | 
/**
 *  A reason this build does not know, from a newer peer or a newer build's database
 *  (D-040). Still a gap: charts draw it as a generic gap band. Not in
 *  [`GapReason::ALL`]; stored as `"unknown"`.
 */
"unknown";

export type GeneralPatch = {
	launch_at_login?: boolean | null,
	show_in_dock?: boolean | null,
	appearance?: Appearance | null,
	check_updates?: boolean | null,
	chart_window?: ChartWindow | null,
};

export type GeneralSettings = {
	launch_at_login: boolean,
	show_in_dock: boolean,
	appearance: Appearance,
	/**  The only network request Kelvo makes; off means none at all. */
	check_updates: boolean,
	/**
	 *  The span of every windowed chart on the module pages (D-091). Absent from a
	 *  settings file written before it existed: 15m.
	 */
	chart_window?: ChartWindow,
};

/**  One local day of the heatmap. */
export type HeatmapDay = {
	date: string,
	/**
	 *  24 hourly averages (percent for `cpu`, °C for `temp`). `null` when no bucket in
	 *  the hour sampled the series (asleep, off, not yet, or an hour that did not exist),
	 *  never 0.
	 */
	hours: (number | null)[],
};

/**  One local day of a [`HeatmapRequest`]. */
export type HeatmapDaySpec = {
	/**  The local date (`2026-10-04`), echoed back in [`HeatmapDay`]. */
	date: string,
	/**
	 *  25 instants: the start of each local hour 00 to 23, then the next local midnight.
	 *  Never decreasing. A local hour that does not exist (spring forward) starts where
	 *  the next one does, so it is empty; a local hour that happens twice (fall back) runs
	 *  to the start of the hour after, two hours later.
	 */
	hour_starts: Millis[],
};

/**  The series a heatmap shows. */
export type HeatmapMetric = 
/**  `cpu.total`. */
"cpu" | 
/**  `thermal.hottest`. */
"temp";

/**
 *  `query_heatmap`: hourly averages for local days. The store knows no time zones: the
 *  frontend sends each local day's hour boundaries in UTC, with DST applied, and Rust
 *  averages whatever buckets start inside each hour.
 */
export type HeatmapRequest = {
	host: HostId,
	metric: HeatmapMetric,
	/**  Oldest first, at most 92. */
	days: HeatmapDaySpec[],
};

/**
 *  What history costs on this machine, measured from the database (`history_growth`):
 *  the whole file, every host together, like `history_size`. The Settings projection
 *  uses it in place of the fill-test model once present.
 */
export type HistoryGrowth = {
	/**  Recorded time the rates are measured over, ms. */
	measured_ms: number,
	/**
	 *  Bytes that do not depend on retention once full: 24 h of 10 s rows and the
	 *  process snapshot window, plus the small tables at their current size.
	 */
	fixed_bytes: ByteCount,
	/**  Bytes one day of 1-minute history costs. */
	minute_day_bytes: ByteCount,
};

/**
 *  What the history store can tell the UI about itself (D-057, D-059): the low-disk pause
 *  and the size-limit trim. Shared by every host, since they share one file.
 */
export type HistoryHealth = {
	/**
	 *  The volume is almost full: 10 s history is not being written ("History paused:
	 *  disk almost full"). Minute history and live values continue.
	 */
	low_disk_paused: boolean,
	/**
	 *  Set once the size limit has trimmed history: it now starts here, ms epoch
	 *  ("History trimmed to stay under 150 MB"). Cleared once retention alone would have
	 *  dropped that history, and when history is cleared.
	 */
	trimmed_before_ms: number | null,
	/**  The size limit in effect at that trim, bytes. */
	trimmed_limit_bytes: number | null,
	/**  False when even the last day does not fit under the limit. */
	cap_met: boolean,
};

/**
 *  Emitted when [`HistoryHealth`] changes: the low-disk pause starts or ends, or a trim
 *  happens or ages out.
 */
export type HistoryHealthChanged = {
	health: HistoryHealth,
};

export type HistoryPage = {
	/**  The tier the points came from. */
	tier: Tier,
	/**
	 *  The width each point averages over, ms: the tier's bucket times the buckets merged
	 *  to stay under `max_points` (a 7d range at 1,008 points: 600,000, "10 MIN AVG"). A
	 *  point at `t` covers `[t, t + bucket_ms)`.
	 */
	bucket_ms: number,
	series: HistorySeries[],
	/**  Gaps overlapping the range. Split lines at these; never interpolate. */
	gaps: Gap[],
};

export type HistoryPatch = {
	retention_days?: number | null,
	size_limit_mb?: number | null,
	network_history?: boolean | null,
};

/**  One merged slot. Slots with no measured value are absent, never zero. */
export type HistoryPoint = {
	t: number,
	min: number | null,
	max: number | null,
	avg: number | null,
};

export type HistoryRequest = {
	host: HostId,
	selectors: SeriesSelector[],
	/**  Inclusive start, ms epoch. */
	from_ms: number,
	/**  Exclusive end, ms epoch. */
	to_ms: number,
	tier: TierRequest,
	/**  Upper bound on points per series; buckets are merged to stay under it. */
	max_points: number,
};

export type HistorySeries = {
	key: SeriesKey,
	points: HistoryPoint[],
	/**
	 *  How long a point stays current, ms (D-092): the hold of the slowest period the
	 *  series is sampled at, or the page's `bucket_ms` if that is larger. Consecutive
	 *  points no more than this apart are one line; further apart, there is a hole
	 *  between them. `gaps` stays the list of explicit holes.
	 * 
	 *  The period is the slowest under the current settings (the backed-off base tick,
	 *  the collector's idle cadence, Performance mode's slowdown), or, when the range
	 *  starts before the last time a period got faster in this app run (a shorter
	 *  sampling interval), the slowest under any settings this run, since the range's
	 *  earlier points were sampled under those. Settings persist across launches, so
	 *  earlier runs count as sampled under the settings this one started with.
	 */
	hold_ms: number,
};

export type HistorySettings = {
	/**  Retention of `tier_1m`, gaps and events; one of [`HistorySettings::RETENTION_DAYS`]. */
	retention_days: number,
	/**
	 *  Cap on the history file, WAL included, in MB (10^6 bytes); one of
	 *  [`HistorySettings::SIZE_LIMITS_MB`]. The oldest history is trimmed to stay under
	 *  it, so it can shorten `retention_days` (D-057, D-059).
	 */
	size_limit_mb: number,
	/**
	 *  "Network history" (D-089): record which apps moved how many bytes, every 10 s
	 *  even with no window open. On by default; off, per-process network rates are
	 *  sampled only while a view shows them (D-082) and nothing new is recorded. The
	 *  `appstore` build never records it. Absent from settings files written before it
	 *  existed: on.
	 */
	network_history?: boolean,
};

/**  Why history is unavailable, for the banner and for whether `reset_history` can help. */
export type HistoryUnavailableReason = 
/**
 *  Another Kelvo process (a second copy, or an installed build next to a dev build
 *  sharing its data) has the database open. Quit it; a reset cannot help.
 */
{ kind: "locked" } | 
/**  A newer Kelvo wrote the database. */
{ kind: "too_new"; found: number; supported: number } | 
/**  The database file is damaged. */
{ kind: "corrupt"; message: string } | 
/**  Anything else: an I/O error opening it, or the local host could not be registered. */
{ kind: "failed"; message: string };

/**  A host's persistent identity. Serialized as the hyphenated UUID string. */
export type HostId = string;

/**  Static facts about a host, read once at startup. */
export type HostInfo = {
	os: OsKind,
	os_version: string,
	/**  Model identifier, for example "Mac15,8". */
	model: string | null,
	/**  Marketing chip name, for example "Apple M3 Max". */
	chip: string | null,
	/**  False when the sensor map does not know this chip; drives the unknown-chip state. */
	chip_known: boolean,
	/**  CPU clusters in the order the collector reports them. Empty when unknown. */
	cpu_topology: ClusterInfo[],
	/**  Exported to TS as `number`; see [`crate::JS_SAFE_INT_MAX`]. */
	mem_total_bytes: number,
	/**  Millisecond epoch. Exported to TS as `number`; see [`crate::JS_SAFE_INT_MAX`]. */
	boot_time_ms: number,
	/**
	 *  The GPU's DVFS operating points in MHz, in the order of `gpu.residency`'s `state`
	 *  labels and without the off state; not necessarily ascending, so the top frequency
	 *  is the largest entry. Empty when unknown, and from a peer or record written before
	 *  D-092.
	 */
	gpu_dvfs_mhz?: number[],
	/**
	 *  The mount points of the boot volume's APFS container that `disk.*` series are
	 *  labelled with, `/` first (`/`, `/System/Volumes/Data`). Empty when unknown, and
	 *  from a peer or record written before D-092.
	 */
	boot_mounts?: string[],
};

/**
 *  A known host as the controller sees it: listed by `list_hosts`, stored in the `hosts`
 *  table. Never sent to a peer; the proto `Hello` carries a [`HostIdentity`].
 */
export type HostRecord = {
	id: HostId,
	/**
	 *  This machine. At most one stored host is local (a partial unique index in the
	 *  store); it is never taken from what a peer says about itself.
	 */
	is_local: boolean,
	/**  User-facing name, for example "MacBook Pro". */
	display_name: string,
	info: HostInfo,
};

/**
 *  Emitted when a host's record changes (the local host learns `chip_known` from its
 *  first capabilities), with every host, local first: what `list_hosts` returns now.
 */
export type HostsChanged = {
	hosts: HostRecord[],
};

/**
 *  A label set: small, sorted by key, keys unique. The invariant is enforced by every
 *  constructor and by deserialization, so two equal label sets always compare, hash and
 *  display the same.
 * 
 *  Serialized (CBOR and JSON) as an array of `[key, value]` pairs in key order. Labels
 *  that arrive out of order are sorted on decode; duplicate keys are a decode error.
 */
export type Labels = ([string, string])[];

/**
 *  One message on a window's live channel (D-049, D-066).
 * 
 *  Order on a fresh subscription: the current `Caps` and `Status`; a `Layout` for every
 *  layout the requested history uses; the most recent two minutes as `Backfill` segments
 *  (each after its `Layout` when that differs from the last one sent); then frames, each
 *  preceded by a `Layout` when the layout changes. History older than two minutes follows
 *  as `BackfillEarlier` chunks, newest first, once the first frame is out: each chunk is
 *  older than everything the channel sent before it.
 * 
 *  After the channel resumes (window shown, display awake, the stream fell behind the
 *  bus): `Caps` and `Status` if they changed, then `Backfill` for exactly the span missed,
 *  in time order and in segments of at most 600 rows (one message each, so applying them
 *  never blocks the webview for long), so `Backfill` rows come after everything already
 *  received.
 * 
 *  `timeline` on `Backfill` and `Frame` numbers the runs of the host's wall clock: the
 *  host bumps it when its clock is stepped (D-064) and for nothing else. Rows with a
 *  `timeline` other than the one held replace everything held at or after their first
 *  row's time. After a step the channel sends the new timeline from its first row (as far
 *  back as the window's backfill span reaches), so that time is where the step happened.
 * 
 *  A subscription that named `series` gets only those series: `Layout.series` lists the
 *  matching keys and every row and frame carries values for them alone.
 */
export type LiveMsg = 
/**
 *  The series of every following `Backfill` and `Frame` with this `layout_no`, in
 *  value order, and each one's catalog kind (`gauge` for a metric this build does not
 *  know). `layout_no` numbers layouts within one engine run.
 */
({ kind: "layout"; layout_no: number; series: SeriesKey[]; kinds: MetricKind[] }) & { capabilities?: never; held?: never; holds_ms?: never; interval_ms?: never; rows?: never; start_ms?: never; timeline?: never; ts_ms?: never; values?: never } | 
/**
 *  Raw measured rows from the engine's one-hour ring: row `i` was taken at about
 *  `start_ms + i * interval_ms`. `null` where a series was not sampled. Segments never
 *  span a hole (sleep, pause, skipped ticks), so a reader never draws across one.
 *  `holds_ms` says, per series, how long a sample in these rows stays current (D-090).
 */
({ kind: "backfill"; layout_no: number; start_ms: number; interval_ms: number; timeline: number; rows: ((number | null)[])[]; holds_ms: number[] }) & { capabilities?: never; held?: never; kinds?: never; series?: never; ts_ms?: never; values?: never } | 
/**
 *  History older than everything sent so far on this channel, in the same shape as
 *  `Backfill`. Its `layout_no` was announced by an earlier `Layout`.
 */
({ kind: "backfill_earlier"; layout_no: number; start_ms: number; interval_ms: number; rows: ((number | null)[])[]; holds_ms: number[] }) & { capabilities?: never; held?: never; kinds?: never; series?: never; timeline?: never; ts_ms?: never; values?: never } | 
/**
 *  How long each series' sample stays current in the frames that follow, in
 *  `layout_no` order (D-090). Sent before the first frame and whenever it changes: a
 *  collector slowing down with no window open, back-off on battery, a thinned
 *  stream. Two samples of a series further apart than the earlier one's hold have a
 *  gap between them; closer ones are one run.
 */
({ kind: "holds"; layout_no: number; holds_ms: number[] }) & { capabilities?: never; held?: never; interval_ms?: never; kinds?: never; rows?: never; series?: never; start_ms?: never; timeline?: never; ts_ms?: never; values?: never } | 
/**
 *  One tick. `values` is what was measured on this tick (`null` for a series not
 *  sampled now); draw charts from it. `held` is the latest value of each series while
 *  it is still current (`null` once stale, D-047); read current numbers and build the
 *  Snapshot from it. Both are in `layout_no` order.
 */
({ kind: "frame"; ts_ms: number; layout_no: number; timeline: number; values: (number | null)[]; held: (number | null)[] }) & { capabilities?: never; holds_ms?: never; interval_ms?: never; kinds?: never; rows?: never; series?: never; start_ms?: never } | 
/**
 *  Process rows, sent only while this window has process interest for the host:
 *  every readable process, or the top rows its [`ProcessView`] asked for, sorted by
 *  the view's first sort key.
 */
({ kind: "processes"; ts_ms: number; rows: LiveProcess[] }) & { capabilities?: never; held?: never; holds_ms?: never; interval_ms?: never; kinds?: never; layout_no?: never; series?: never; start_ms?: never; timeline?: never; values?: never } | ({ kind: "caps"; capabilities: Capabilities }) & { held?: never; holds_ms?: never; interval_ms?: never; kinds?: never; layout_no?: never; rows?: never; series?: never; start_ms?: never; timeline?: never; ts_ms?: never; values?: never } | 
/**  Engine state, sent when it changes. */
{
	kind: "status",
} & LiveStatus;

/**  One process at one sample (v1-local-monitor.md 6.2). */
export type LiveProcess = {
	pid: number,
	/**
	 *  Process start, microseconds since the Unix epoch. With `pid` it identifies the
	 *  process, since pids are reused.
	 */
	start_time_us: number,
	name: string,
	/**  Percent of one core; can exceed 100. */
	cpu_pct: number | null,
	mem_bytes: number,
	/**  `null` when the platform does not say. */
	compressed_bytes: number | null,
	threads: number,
	idle_wakeups_per_s: number | null,
	energy: number | null,
	disk_read_bps: number | null,
	disk_write_bps: number | null,
	/**
	 *  Bytes per second received, loopback excluded. `null` when per-process network was
	 *  not sampled: no visible view asked for it (`ProcessView.network`), or
	 *  `Capabilities.process_network` is false. Covers the current user's processes only
	 *  (D-081).
	 */
	net_rx_bps: number | null,
	/**  Bytes per second sent; see `net_rx_bps`. */
	net_tx_bps: number | null,
	/**
	 *  Share of the whole GPU over the interval, 0 to 100: the GPU time the process's
	 *  work used divided by wall time. `null` when not sampled: no visible view asked for
	 *  it (`ProcessView.gpu`), or `Capabilities.process_gpu` is false. Approximate while
	 *  a long compute job runs: time is charged when a command buffer completes (D-085).
	 */
	gpu_pct: number | null,
	/**
	 *  TCP ports the process listens on, ascending; empty when none. `null` when not read:
	 *  no visible view asked for them (`ProcessView.ports`). Covers the current user's
	 *  processes only, like every row.
	 */
	ports: number[] | null,
	user: string,
	/**
	 *  Why Quit and Force Quit refuse this process, `null` when they may signal it: the
	 *  rule `process_signal` checks, with Kelvo's own processes from the self-CPU
	 *  collector's list (D-092).
	 */
	refusal: SignalRefusal | null,
};

export type LiveStatus = {
	/**  The base tick in effect, after battery back-off. */
	interval_ms: number,
	/**
	 *  How often this channel sends frames: the base tick, or the multiple of it the
	 *  subscription's `min_period_ms` thins frames to. Stale is measured in these.
	 */
	frame_period_ms: number,
	paused: boolean,
	/**
	 *  The display is asleep or the screen locked: no frames are sent until it wakes,
	 *  then the missed span arrives as `Backfill`. Not stale.
	 */
	display_idle: boolean,
	on_battery: boolean,
	/**
	 *  Whether Performance mode is in effect, and why: the setting or Low Power Mode
	 *  (D-088). Frames are paced to at least 2 s while it is.
	 */
	performance: PerformanceReason,
	/**
	 *  Battery, adapter or charging, read with `on_battery`; a Mac without a battery is
	 *  `adapter` (D-092).
	 */
	power_source: PowerSource,
	/**
	 *  The `iface` label of the reported interface carrying the default route, `null`
	 *  when the route is on an interface Kelvo does not report (a VPN tunnel) or there is
	 *  none. Re-read on interface changes and every 60 s (D-092).
	 */
	primary_iface: string | null,
};

/**  GB (10^9) or GiB (2^30). */
export type MemoryUnit = "decimal" | "binary";

/**
 *  How a module appears in the menu bar (4.2, 4.15). Not every mode is valid for every
 *  module; see [`MenuBarMode::allowed_for`].
 */
export type MenuBarMode = 
/**  A bar in the combined item (CPU, GPU, Memory). */
"in_combined" | 
/**  Its own value with a label. */
"value_label" | 
/**  Temperature in the combined item (Power & Sensors). */
"temp_in_combined" | 
/**  System watts as a value (Power & Sensors). */
"watts_value" | 
/**
 *  A status item of its own showing the module's graph ("Graphs" and "Cores +
 *  histogram"): CPU sparkline, GPU history bars, memory fill gauge, network
 *  up and down rates (D-080).
 */
"own_graph" | 
/**  A status item of its own showing the labelled value (watts for Power & Sensors). */
"own_value" | 
/**  A status item of its own showing CPU per-core load, P cores then E cores (CPU only). */
"own_cores" | "hidden";

/**
 *  Dotted, stable, lowercase metric name such as `cpu.load` or `power.cpu`. Never reused
 *  for a different meaning; renaming one is a decision entry.
 * 
 *  Allowed characters are `a-z`, `0-9`, `_` and `.`, with no empty segment. Construct
 *  known IDs with [`MetricId::from_static`] and untrusted ones with [`MetricId::parse`].
 *  Deserialization does not validate: a malformed ID from a peer is simply an unknown
 *  metric, and unknown metrics are ignored by every receiver.
 */
export type MetricId = string;

/**  How a metric's values behave over time. */
export type MetricKind = 
/**  A level read at the sample time. */
"gauge" | 
/**  Per-second rate over the span since the series' previous sample. */
"rate" | 
/**
 *  The mean over the span since the series' previous sample: a counter delta such as
 *  CPU load, residency or energy turned into watts (D-090). A collector that slows
 *  down still covers every second, at a coarser resolution.
 */
"mean" | 
/**
 *  Monotonic counter. Collectors convert counters to rates, so no v1 metric is a
 *  counter; the variant exists for v4 sources that may send raw counters.
 */
"counter";

/**
 *  A process start time in microseconds since the Unix epoch, as `LiveProcess` carries
 *  it, passed as a plain JS `number` (D-039).
 */
export type Micros = number;

/**  A millisecond epoch timestamp passed as a plain JS `number` (D-039). */
export type Millis = number;

/**
 *  A UI and settings module. Every metric belongs to exactly one.
 * 
 *  Serialized in snake_case (`"cpu"`), the same text the store writes to `gaps.module`.
 *  The UI shows `Power` and `Sensors` as one "Power & Sensors" module; see
 *  [`crate::settings`] for how settings treat the pair.
 */
export type Module = "cpu" | "gpu" | "memory" | "power" | "sensors" | "network" | "disk" | "battery" | 
/**
 *  A module this build does not know, sent by a newer peer or written by a newer
 *  build (D-040). Never produced locally and not in [`Module::ALL`]. Consumers skip
 *  it: capabilities and settings drop it on decode, the store skips its gaps.
 */
"unknown";

/**
 *  The UI maps these to its three states: data, "not available" and unknown chip.
 * 
 *  Deserialization is hand-written so that a state added by a newer peer, with or without
 *  content, decodes as [`ModuleCap::Unknown`] instead of failing the whole message
 *  (`#[serde(other)]` only covers content-free values; D-038, D-040).
 */
export type ModuleCap = 
/**  The module produces `series` series. */
({ available: {
	series: number,
} }) & { unsupported?: never } | 
/**  A collector exists for the module but cannot run. */
({ unsupported: UnsupportedReason }) & { available?: never } | 
/**  The host does not have this hardware (no battery on a Mac mini). */
"not_present" | 
/**
 *  A state this build does not know (D-040). Never produced locally; the UI shows it
 *  like "not available".
 */
"unknown";

export type ModulePatch = {
	enabled?: boolean | null,
	menu_bar?: MenuBarMode | null,
};

export type ModuleSettings = {
	enabled: boolean,
	menu_bar: MenuBarMode,
};

/**
 *  Sent to the `dashboard` window only, when `open_dashboard` asks an existing window to
 *  show `route` (for example `/dashboard/settings`). A newly created dashboard loads its
 *  route as the URL path instead.
 */
export type NavigateRequested = {
	route: string,
};

/**  The primary interface's addresses (`get_network_addresses`). */
export type NetworkAddresses = {
	/**  The interface carrying the default route, as `LiveStatus.primary_iface`. */
	iface: string | null,
	/**  Dotted quads, in the order the system lists them. */
	ipv4: string[],
	/**  Link-local addresses are left out. */
	ipv6: string[],
};

/**
 *  `query_network_by_app`: which apps moved the interface's bytes over a range (D-089).
 * 
 *  Per direction, outside a clamp, the parts add up to the interface total exactly:
 *  `sum(apps) + other_apps + overhead + system == iface`.
 */
export type NetworkByApp = {
	/**
	 *  The range the sums cover: the request widened to whole buckets (10 s, or 1 m and
	 *  15 m for older history), so the UI should draw this, not what it asked for.
	 */
	from_ms: number,
	to_ms: number,
	/**
	 *  Buckets before this are complete; from here to `to_ms` they are still open in the
	 *  engine (one of the per-app and interface streams has not reported past them) or
	 *  not reached yet, so they still grow and their remainder is not meaningful yet.
	 *  With nothing open, the end of what the engine closed, or the start of the 10 s
	 *  bucket it last (re)started in. Equal to `to_ms` when
	 *  the whole range is complete, and may be before `from_ms` when none of it is. A
	 *  range is final, and can be cached, only once this reaches `to_ms`.
	 */
	complete_to_ms: number,
	/**
	 *  Width of the coarsest bucket used, ms: the precision the range can be labelled
	 *  with. 10,000 when nothing was recorded.
	 */
	resolution_ms: number,
	/**  How much of `[from_ms, to_ms)` was measured, ms ("measured for 40 of 90 s"). */
	measured_ms: number,
	/**  `[from_ms, to_ms)` in consecutive spans by the tier that answered each. */
	coverage: NetworkSpan[],
	/**  Named apps, largest rx + tx first. "Other apps" is not among them. */
	apps: AppBytes[],
	/**
	 *  Apps folded together: below a stored bucket's top 20, nameless, or past the cap
	 *  on new names per hour.
	 */
	other_apps_rx_bytes: number,
	other_apps_tx_bytes: number,
	/**  Interface totals over the measured spans. */
	iface_rx_bytes: number,
	iface_tx_bytes: number,
	/**
	 *  "Protocol overhead (est.)": interface packets times a per-packet header size,
	 *  shrunk to what the apps leave of the interface total.
	 */
	overhead_rx_bytes: number,
	overhead_tx_bytes: number,
	/**
	 *  "System and other": interface minus apps, other apps and overhead, never below 0.
	 *  Root daemons (software update, mDNSResponder, backups) that Kelvo cannot see.
	 */
	system_rx_bytes: number,
	system_tx_bytes: number,
	/**
	 *  The apps moved more than the interface did: tunnelled traffic (a userspace VPN)
	 *  counted twice. `system_*` is then 0 and the parts exceed the total.
	 */
	clamped: boolean,
};

/**  One sub-range of a `query_network_by_app` range and the tier that answered it. */
export type NetworkSpan = {
	from_ms: number,
	to_ms: number,
	/**
	 *  `s10`, `m1` or `m15`; `null` when nothing was recorded there (before collection
	 *  started, asleep, paused, Network history off).
	 */
	tier: Tier | null,
};

/**  MB/s or Mb/s. */
export type NetworkUnit = "bytes_per_sec" | "bits_per_sec";

export type OnboardingPatch = {
	completed?: boolean | null,
};

export type OnboardingSettings = {
	completed: boolean,
};

export type OsKind = "mac_os" | "linux" | 
/**  An OS this build does not know, from a newer peer (D-040). */
"unknown";

/**  Why Performance mode is in effect (D-088). */
export type PerformanceReason = "off" | 
/**  The user turned it on in Settings. */
"setting" | 
/**  macOS Low Power Mode is on and the setting is off. It ends with Low Power Mode. */
"low_power_mode";

/**  What the engine, the tray and the live stream run at on one power source. */
export type PlanFigures = {
	/**  The engine's base tick with a window open (`effective_interval_ms`). */
	tick_ms: number,
	/**
	 *  The base tick with the menu bar only, in the background (D-094):
	 *  `background_interval_ms` of `tick_ms`.
	 */
	background_tick_ms: number,
	/**
	 *  The shortest time between two menu bar draws in the background: the tray pacer's
	 *  period, or the background tick when that is longer.
	 */
	menu_bar_ms: number,
	/**  How often a visible window gets frames: the tick, or Performance mode's floor. */
	window_ms: number,
	/**  The shortest time between two menu bar draws with a window open. */
	window_menu_bar_ms: number,
	/**  The process collector's period with a window open that lists no processes. */
	window_idle_processes_ms: number,
	/**  The process collector's period in the background. */
	background_processes_ms: number,
	/**
	 *  The temperature collectors' period in the background, a temperature in the menu
	 *  bar included.
	 */
	background_temperatures_ms: number,
};

export type PowerComponent = "package" | "ane";

/**
 *  What powers the Mac right now (D-092), from the same power-source notification the
 *  battery back-off reacts to. A Mac without a battery is always on `Adapter`.
 */
export type PowerSource = 
/**  Running on the battery. */
"battery" | 
/**  On external power, the battery not charging (full, held at a limit, or no battery). */
"adapter" | 
/**  On external power and the battery is charging. */
"charging";

/**  One process's energy over a `query_energy_by_app` range (D-093). */
export type ProcessEnergy = {
	pid: number,
	/**  With `pid`, the process's identity, as on `LiveProcess`. */
	start_time_us: number,
	name: string,
	/**  Joules over the range. */
	energy_j: number | null,
	/**  Average watts over the range's measured span. */
	avg_w: number | null,
	/**  It was in the newest process sample. An exited process cannot be quit. */
	running: boolean,
	/**
	 *  Why Quit and Force Quit refuse it, as on `LiveProcess`; `null` for an exited
	 *  process too, which has nothing to quit.
	 */
	refusal: SignalRefusal | null,
};

export type ProcessResolution = 
/**
 *  The top 30 by CPU at one instant (every 10 s, or 30 s in Performance mode; kept
 *  72 hours).
 */
"snapshot" | 
/**  The top 5 by CPU averaged over one minute (the last 7 days). */
"top5_per_minute" | 
/**
 *  The top 5 by CPU averaged over 15 minutes (older than 7 days, for the rest of the
 *  retention period).
 */
"top5_per_15_minutes";

/**
 *  Why `process_signal` did not signal. Serialized with a `kind` tag like `CommandError`;
 *  the host variants share `CommandError`'s names and shapes.
 */
export type ProcessSignalError = 
/**  On the refuse list. */
{ kind: "refused"; refusal: SignalRefusal } | 
/**  The process exited before the signal was sent. */
{ kind: "not_found" } | 
/**  The PID now belongs to a process with a different start time. Nothing was sent. */
{ kind: "pid_reused" } | 
/**  `EPERM`: another user's process. Kelvo never escalates. */
{ kind: "permission_denied" } | 
/**  No host with this id is registered. */
{ kind: "unknown_host"; host: HostId } | 
/**  The host is not this Mac. Signals do not cross the wire in v1 (D-029). */
{ kind: "remote_host"; host: HostId } | 
/**
 *  This edition cannot signal processes (the sandboxed App Store build). The UI
 *  learns it up front from `get_edition` and should not offer the actions.
 */
{ kind: "unavailable" } | 
/**  The OS failed in a way none of the above covers. */
{ kind: "failed"; message: string };

/**  A descending sort key for [`ProcessView`]. */
export type ProcessSort = "cpu" | "memory" | "threads" | "wakeups" | "energy" | "disk_read" | "disk_write" | 
/**  Read plus write. */
"disk_total" | 
/**  Network receive rate. Rows without a rate rank last. */
"net_rx" | 
/**  Network send rate. */
"net_tx" | 
/**  Receive plus send. */
"net_total" | 
/**  Share of the GPU. Rows without a value rank last. */
"gpu";

/**  How a window wants process rows (`set_process_interest`). */
export type ProcessView = {
	/**
	 *  Rows per sort key: the batch is the union of the top `limit` processes by each
	 *  key in `sort`. `null` sends every readable process (the Processes table).
	 */
	limit: number | null,
	/**  The keys the window ranks by. Empty means CPU. */
	sort: ProcessSort[],
	/**
	 *  At most one batch per this many ms (`null`: every sample, each base tick). The
	 *  collector itself slows down to the shortest period any visible window asks for.
	 */
	period_ms: number | null,
	/**
	 *  The window shows per-process network rates. While a visible window does, the host
	 *  samples NetworkStatistics on the process ticks; otherwise it holds nothing open
	 *  and rows carry `null` rates (D-081).
	 */
	network?: boolean,
	/**
	 *  The window shows per-process GPU time. While a visible window does, the host reads
	 *  the GPU's IORegistry clients on the process ticks; otherwise rows carry `null`.
	 */
	gpu?: boolean,
	/**
	 *  The window shows the TCP ports processes listen on. While a visible window does,
	 *  the host reads each process's sockets on the process ticks (each process at most
	 *  every 5 s); otherwise rows carry `null`.
	 */
	ports?: boolean,
};

/**  `query_processes_at`: the stored processes nearest a moment. */
export type ProcessesAt = {
	/**  The snapshot's time, or the start of the minute or 15 minutes. */
	ts_ms: number,
	resolution: ProcessResolution,
	rows: StoredProcess[],
};

export type SamplingPatch = {
	interval_ms?: number | null,
	slow_on_battery?: boolean | null,
	performance_mode?: boolean | null,
};

/**
 *  The sampling plan for one combination of settings and power state (D-092). The table
 *  covers the whole input domain, so the Settings panel can show what another choice
 *  would do ("on battery it would be...") by reading a row.
 */
export type SamplingPlan = {
	interval_ms: number,
	slow_on_battery: boolean,
	/**
	 *  Performance mode in effect. The engine turns it on under Low Power Mode, so rows
	 *  with `low_power_mode` and without `performance` never run: they say what the mode
	 *  changes there.
	 */
	performance: boolean,
	low_power_mode: boolean,
	ac: PlanFigures,
	battery: PlanFigures,
};

export type SamplingSettings = {
	/**  Base tick; one of [`SamplingSettings::INTERVALS_MS`] (0.5 s to 60 s). */
	interval_ms: number,
	/**  On battery (or Low Power Mode) the base tick doubles, capped at 60 s. */
	slow_on_battery: boolean,
	/**
	 *  Performance mode (D-088): the background and visible levers that trade update
	 *  rate and motion for CPU. Low Power Mode turns it on too, without changing this
	 *  value; [`PerformanceReason::resolve`] gives the effective state. Absent from a
	 *  settings file written before it existed: off.
	 */
	performance_mode?: boolean,
};

/**
 *  `sensor_dump` (v1-local-monitor.md 4.17). No serial numbers, user names, host names or
 *  network identifiers.
 */
export type SensorDump = {
	model: string | null,
	chip: string | null,
	os_version: string,
	chip_known: boolean,
	capabilities: Capabilities,
	/**
	 *  Every Power and Sensors series in the current layout with its latest value
	 *  (`null` when stale), in layout order.
	 */
	sensors: SensorReading[],
};

export type SensorReading = {
	key: SeriesKey,
	value: number | null,
};

/**
 *  One series: a metric plus its labels. Display form `cpu.load{core=7}`.
 * 
 *  On the wire and over IPC it is a struct `{ metric, labels }`; keys always travel as
 *  strings, never as a store's interned IDs.
 */
export type SeriesKey = {
	metric: MetricId,
	labels: Labels,
};

/**  Picks series by metric and a label subset. Used by alert rules and history queries. */
export type SeriesSelector = {
	metric: MetricId,
	/**  Empty matches any labels. Otherwise every pair must appear in the series' labels. */
	labels: Labels,
};

export type Settings = {
	/**
	 *  One entry per settings module: every [`Module`] except `Sensors`. An entry for a
	 *  module this build does not know (a settings file from a newer build) is dropped on
	 *  decode (D-040).
	 */
	modules: Partial<{ [key in Module]: ModuleSettings }>,
	sampling: SamplingSettings,
	history: HistorySettings,
	units: UnitSettings,
	general: GeneralSettings,
	onboarding: OnboardingSettings,
	/**  Absent from a settings file written before v1.2: both alerts off. */
	alerts?: AlertSettings,
};

/**  Emitted after every settings change, with the full new settings. */
export type SettingsChanged = {
	revision: number,
	settings: Settings,
};

/**  A partial change. Every field is optional; absent fields keep their value. */
export type SettingsPatch = {
	modules?: Partial<{ [key in Module]: ModulePatch }> | null,
	sampling?: SamplingPatch | null,
	history?: HistoryPatch | null,
	units?: UnitsPatch | null,
	general?: GeneralPatch | null,
	onboarding?: OnboardingPatch | null,
	alerts?: AlertsPatch | null,
};

/**
 *  Settings with the revision they were current at. Revisions increase by one per change
 *  within an app run; a window drops a `settings-changed` event older than what it holds.
 */
export type SettingsSnapshot = {
	revision: number,
	settings: Settings,
};

/**  What to ask of the process. */
export type SignalKind = 
/**  `NSRunningApplication.terminate` for a regular app, `SIGTERM` otherwise. */
"quit" | 
/**  `NSRunningApplication.forceTerminate` for a regular app, `SIGKILL` otherwise. */
"force_quit";

/**  Why Kelvo will not signal a process. The UI words it (`process-signal.ts`). */
export type SignalRefusal = 
/**  The macOS kernel (pid 0), or a pid kill(2) would treat as a process group. */
"kernel_task" | "launchd" | "window_server" | "login_window" | 
/**  Kelvo itself or one of its helpers. */
"kelvo";

/**  A process as the store keeps it: fewer fields than [`LiveProcess`]. */
export type StoredProcess = {
	name: string,
	pid: number,
	cpu_pct: number | null,
	mem_bytes: number,
	threads: number,
	idle_wakeups_per_s: number | null,
	energy: number | null,
};

/**  What `subscribe_live` did before returning. */
export type SubscriptionInfo = {
	host: HostId,
	/**
	 *  This subscription's id (the channel's): pass it to `set_process_interest` so the
	 *  interest belongs to this page load and ends with it.
	 */
	stream: number,
	/**
	 *  Start of the backfill already sent on the channel, `null` when none was (the ring is
	 *  empty, or the window is hidden and the channel starts when it is shown).
	 */
	backfill_start_ms: number | null,
	/**  Backfill rows sent, over all segments. */
	backfill_rows: number,
	/**
	 *  Start of the older history that follows as `BackfillEarlier` chunks, `null` when
	 *  none does.
	 */
	earlier_start_ms: number | null,
	/**  Rows still to come in `BackfillEarlier` chunks. */
	earlier_rows: number,
};

export type TemperatureUnit = "celsius" | "fahrenheit";

/**
 *  `NSProcessInfo.thermalState`, the value of the `thermal.state` metric. Ordered, so
 *  `state >= ThermalState::Serious` reads naturally.
 */
export type ThermalState = "nominal" | "fair" | "serious" | "critical";

/**
 *  A resolution of data. [`Tier::S10`], [`Tier::M1`] and [`Tier::M15`] are persisted and
 *  synced; [`Tier::Live1s`] is the in-memory ring buffer and the live stream. M1 keeps the
 *  last 7 days; older minutes are rolled down into M15 for the rest of the retention.
 */
export type Tier = "live1s" | "s10" | "m1" | 
/**
 *  15-minute buckets: minutes older than the M1 window, rolled down by the store.
 *  Older peers decode it as [`Tier::Unknown`] (D-040); it is synced only when both
 *  sides negotiated [`SyncRowKind::M15`].
 */
"m15" | 
/**
 *  A tier this build does not know, named by a newer peer (D-040). It has no bucket
 *  width and is never persisted; a sync request for it is answered with an error.
 */
"unknown";

/**  Which tier `query_history` reads. */
export type TierRequest = 
/**
 *  10 s buckets while they cover the start of the range (24 h); otherwise 1 min while
 *  minutes cover it (7 days), else 15 min.
 */
"auto" | "s10" | "m1";

export type UnitSettings = {
	temperature: TemperatureUnit,
	network: NetworkUnit,
	memory: MemoryUnit,
};

export type UnitsPatch = {
	temperature?: TemperatureUnit | null,
	network?: NetworkUnit | null,
	memory?: MemoryUnit | null,
};

export type UnsupportedReason = 
/**  The sensor map does not know this chip yet ("Share sensor dump"). */
"unknown_chip" | 
/**
 *  The build cannot hold the entitlement the collector needs ("not available in this
 *  edition").
 */
"missing_entitlement" | 
/**  The API is there but reports no such hardware. */
"no_hardware" | 
/**
 *  A reason this build does not know (D-040). The UI shows a generic
 *  "not available".
 */
"unknown";

/**
 *  `check_for_updates`. The updater lands in phase 6; until then the command reports that
 *  no update source is configured, and never makes a network request.
 */
export type UpdateStatus = 
/**  "Check for updates automatically" is off; nothing was requested. */
{ kind: "disabled" } | 
/**  This build has no update source yet. */
{ kind: "not_configured" };

/**
 *  What every window root reflects as attributes: `data-performance`,
 *  `data-reduce-transparency` and the theme.
 */
export type WindowAppearance = {
	/**
	 *  Whether Performance mode is in effect, and why (D-088). Any reason but `off`
	 *  turns all motion off.
	 */
	performance: PerformanceReason,
	/**  The macOS Reduce Transparency accessibility setting. */
	reduce_transparency: boolean,
	/**
	 *  The user's Appearance setting. `system` follows `prefers-color-scheme`; Rust also
	 *  sets the native window theme, so vibrancy and the CSS media query agree.
	 */
	theme: Appearance,
};

/**  Emitted when Performance mode, Reduce Transparency or the theme changes. */
export type WindowAppearanceChanged = {
	appearance: WindowAppearance,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

